function box(x,z,w,h,d,material,opts={}){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);m.position.set(x,h/2,z);m.castShadow=true;m.receiveShadow=true;scene.add(m);if(opts.collide!==false)obstacles.push({x,z,r:Math.max(w,d)*.48});return m}
