// Roadside warning beacons, rubble stains and painted safe-zone markings.
for(let i=0;i<14;i++){const x=(Math.random()-.5)*90,z=(Math.random()-.5)*90;if(Math.abs(x)<13&&Math.abs(z)<13)continue;flatCircle(x,z,.35+Math.random()*1.2,0x291e1a,.22)}
for(const [x,z] of [[-5,-4],[5,-4],[-5,4],[5,4]]){const stripe=new THREE.Mesh(new THREE.BoxGeometry(2.4,.03,.18),yellow);stripe.position.set(x,.055,z);scene.add(stripe)}
const player={group:new THREE.Group(),health:100,ammo:12,reserve:60,score:0,kills:0,medkits:2,alive:true,sprinting:false,fireAt:0,reloadAt:0,invuln:0};scene.add(player.group);player.group.position.set(0,0,0);player.group.rotation.y=Math.PI;
function makePerson({isPlayer=false,tone=0x9a8f7a,shirt=0x344c3e}){const root=new THREE.Group(), clothes=mat(shirt),skin=mat(tone),pants=mat(isPlayer?0x323d38:0x555246),boot=mat(0x282923),white=mat(0xd0c8b0),black=mat(0x171b18,.45),red=mat(0x843d31);const body=new THREE.Mesh(new THREE.BoxGeometry(.55,.74,.34),clothes);body.position.y=1.08;body.castShadow=true;root.add(body);const vest=new THREE.Mesh(new THREE.BoxGeometry(.59,.43,.365),mat(isPlayer?0x536047:0x5c5547));vest.position.set(0,1.08,.015);vest.castShadow=true;root.add(vest);const head=new THREE.Mesh(new THREE.SphereGeometry(.22,12,10),skin);head.position.set(0,1.66,.015);head.scale.set(.86,1.1,.9);head.castShadow=true;root.add(head);const eye1=new THREE.Mesh(new THREE.SphereGeometry(.035,7,6),isPlayer?black:red),eye2=eye1.clone();eye1.position.set(-.085,1.69,.195);eye2.position.set(.085,1.69,.195);root.add(eye1,eye2);const legL=new THREE.Group(),legR=new THREE.Group();legL.position.set(-.16,.72,0);legR.position.set(.16,.72,0);for(const [g] of [[legL],[legR]]){const leg=new THREE.Mesh(new THREE.BoxGeometry(.22,.62,.25),pants);leg.position.y=-.28;leg.castShadow=true;g.add(leg);const foot=new THREE.Mesh(new THREE.BoxGeometry(.23,.14,.36),boot);foot.position.set(0,-.56,.06);g.add(foot);root.add(g)}const armL=new THREE.Group(),armR=new THREE.Group();armL.position.set(-.34,1.34,0);armR.position.set(.34,1.34,0);for(const [g,side] of [[armL,-1],[armR,1]]){const upper=new THREE.Mesh(new THREE.BoxGeometry(.19,.5,.21),clothes);upper.position.y=-.22;upper.castShadow=true;g.add(upper);const hand=new THREE.Mesh(new THREE.SphereGeometry(.105,8,7),skin);hand.position.y=-.48;g.add(hand);root.add(g)}if(isPlayer){const pack=new THREE.Mesh(new THREE.BoxGeometry(.34,.48,.2),mat(0x3c4538));pack.position.set(0,1.17,-.23);root.add(pack);const gun=new THREE.Group();const barrel=new THREE.Mesh(new THREE.BoxGeometry(.09,.11,.5),metal);barrel.position.set(0,1.23,.38);gun.add(barrel);const grip=new THREE.Mesh(new THREE.BoxGeometry(.085,.24,.13),mat(0x282d29));grip.position.set(0,1.08,.27);gun.add(grip);const sight=new THREE.Mesh(new THREE.BoxGeometry(.035,.035,.14),black);sight.position.set(0,1.3,.35);gun.add(sight);root.add(gun);root.userData.gun=gun}return {root,legL,legR,armL,armR}}
const playerModel=makePerson({isPlayer:true});player.group.add(playerModel.root);player.model=playerModel;flatCircle(0,0,.62,0x090d0b,.42);
const zombies=[],pickups=[],particles=[];const clock=new THREE.Clock();const plane=new THREE.Plane(new THREE.Vector3(0,1,0),0),raycaster=new THREE.Raycaster();const mouse=new THREE.Vector2(0,0);let pointerMoved=false,playing=false,paused=false,elapsed=0,wave=1,waveTime=0,spawnTimer=1,fireHeld=false,toastTimer=0,hitFlash=0,shake=0,lastAim=new THREE.Vector3(0,0,-1),touch={x:0,y:0},joystickId=null,prevTime=performance.now();
function makeZombie(x,z){const tones=[0x8c9990,0x9e9a80,0x777e70,0xb0a18a],shirts=[0x56493c,0x56604e,0x52564f,0x624f49];const m=makePerson({tone:tones[(Math.random()*tones.length)|0],shirt:shirts[(Math.random()*shirts.length)|0]});const group=m.root;group.position.set(x,0,z);group.rotation.y=Math.random()*Math.PI*2;scene.add(group);const shadow=flatCircle(x,z,.62,0x080b09,.37);const hp=1+Math.floor(wave/4);zombies.push({group,model:m,x,z,hp,maxHp:hp,attack:0,anim:Math.random()*6,speed:1.05+Math.random()*.32+wave*.055,shadow,hit:0})}
function spawnZombie(){const a=Math.random()*Math.PI*2,r=25+Math.random()*14;let x=Math.cos(a)*r,z=Math.sin(a)*r;if(Math.abs(x)>46)x=Math.sign(x)*45;if(Math.abs(z)>46)z=Math.sign(z)*45;for(const o of obstacles)if(Math.hypot(x-o.x,z-o.z)<o.r+1){x+=4;z-=3}makeZombie(x,z)}
function makePickup(x,z,type){const group=new THREE.Group();group.position.set(x,.45,z);const color=type==='ammo'?0xd8f36a:0x68c987;const gem=new THREE.Mesh(new THREE.OctahedronGeometry(.27,0),mat(color,.35,.15));gem.position.y=.35;gem.castShadow=true;group.add(gem);const ring=new THREE.Mesh(new THREE.TorusGeometry(.35,.035,6,16),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.8}));ring.rotation.x=Math.PI/2;group.add(ring);scene.add(group);pickups.push({group,type,x,z,phase:Math.random()*6})}
function updateHUD(){document.querySelector('#healthbar').style.width=Math.max(0,player.health)+'%';document.querySelector('#healthnum').textContent=Math.ceil(player.health);document.querySelector('#ammo').textContent=player.ammo;document.querySelector('#reserve').textContent=player.reserve;document.querySelector('#score').textContent=String(player.score).padStart(4,'0');document.querySelector('#day').textContent=String(wave).padStart(2,'0');document.querySelector('#wave').textContent=`NIGHT ${String(wave).padStart(2,'0')}`;document.querySelector('#wavebar').style.width=`${Math.min(100,waveTime/35*100)}%`;document.querySelector('#wave-sub').textContent=player.health<30?'CRITICAL CONDITION':zombies.length?`${zombies.length} HOSTILES NEARBY`:'THEY ARE COMING';document.querySelector('#healBtn').querySelector('span').textContent=`MED ${player.medkits}`}
function toast(text){const e=document.querySelector('#toast');e.textContent=text;e.classList.add('on');toastTimer=1.6}

